-- Additional schema-valid recovery jobs after the unchanged attempt-read seed.
SELECT ('00000000-0000-0000-0000-'||lpad((6000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000002008',stage,run,state,3,'fixture-'||stage,
'{"track":"é😀","steps":[{"name":"producer","revision":"1"},{"name":"legacy-step","revision":"r"}],"parameters":{"wide":123456789012345678901234567890,"decimal":1.25,"nested":[null,false]},"output_prefix":"jobs/é😀"}',600,'2001-02-03T04:05:06.123456Z',CASE WHEN state<>'pending' THEN '00000000-0000-0000-0000-000000000023'::uuid END,'historical',CASE WHEN state<>'pending' THEN 'token:é😀' END,n,CASE WHEN state='claimed' THEN sha256(convert_to('fixture-'||n,'UTF8')) END,CASE WHEN state='claimed' THEN '2099-01-01Z'::timestamptz END,CASE WHEN state<>'pending' THEN '2001-02-03T04:05:07Z'::timestamptz END,CASE WHEN state<>'pending' THEN '2099-01-01Z'::timestamptz END,CASE WHEN state IN ('completed','failed') THEN '2001-02-03T04:05:08Z'::timestamptz END,CASE WHEN state='completed' THEN '00000000-0000-0000-0000-000000003008'::uuid END,CASE WHEN state='completed' THEN '00000000-0000-0000-0000-000000007001'::uuid END,CASE WHEN state='failed' THEN 'step' END,CASE WHEN state='failed' THEN 'opaque_code' END,CASE WHEN state='failed' THEN 'é😀 failed' END,'[{"key":"logs/é😀","size_bytes":5,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]',origin,CASE WHEN origin<>'submission' THEN '00000000-0000-0000-0000-000000006001'::uuid END
FROM (VALUES(1,'evaluator',1,'completed','submission'),(2,'evaluator',2,'failed','auto_retry'),(3,'evaluator',3,'claimed','human_retry'),(4,'tester',1,'failed','submission'),(5,'tester',2,'completed','auto_retry'),(6,'tester',3,'pending','human_retry')) AS x(n,stage,run,state,origin);
